// Generates THIRD_PARTY_LICENSES.md for the packages bundled into the app
// (renderer + main bundles) plus Electron itself. Dev-only tools are not shipped.
import { readFileSync, writeFileSync, existsSync, readdirSync } from 'node:fs';
import { join } from 'node:path';

const SHIPPED = ['electron', 'react', 'react-dom', 'scheduler', 'zod', 'fflate'];
const out = [
  '# Third-party licenses',
  '',
  'Packages bundled into Maybe Pile builds. Generated by `npm run licenses`.',
  '',
];
for (const name of SHIPPED) {
  const dir = join('node_modules', name);
  const pkg = JSON.parse(readFileSync(join(dir, 'package.json'), 'utf8'));
  out.push(`## ${name} ${pkg.version}`, '', `License: ${pkg.license ?? 'see file'}`, '');
  const file = readdirSync(dir).find((f) => /^licen[cs]e/i.test(f));
  if (file && existsSync(join(dir, file)))
    out.push('```', readFileSync(join(dir, file), 'utf8').trim(), '```', '');
}
out.push(
  '## Chromium, Node.js and their dependencies',
  '',
  'Distributed with Electron; see `LICENSES.chromium.html` inside each packaged app.',
  '',
);
writeFileSync('THIRD_PARTY_LICENSES.md', out.join('\n'));
console.log(`THIRD_PARTY_LICENSES.md written (${SHIPPED.length} packages)`);
